input.command:
cat > ~/.claude/ccgate.jsonnet <<'EOF'
// ccgate global config: embedded default rules, provider switched to the
// local OpenAI-compatible endpoint.
{
  provider: {
    name: 'openai',
    model: 'gpt-6-astra',
    base_url: 'http://127.0.0.1:8787/v1',
  },
}
EOF
cat > ~/.claude/settings.json <<'EOF'
{
  "env": {
    "OPENAI_BASE_URL": "http://127.0.0.1:8787/v1",
    "OPENAI_API_KEY": "sk-sandbox-proxy",
    "CCGATE_OPENAI_API_KEY": "sk-sandbox-proxy"
  },
  "hooks": {
    "PermissionRequest": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "/home/runner/.local/bin/ccgate claude"
          }
        ]
      }
    ]
  }
}
EOF
python3 -I -m json.tool ~/.claude/settings.json >/dev/null && echo ok

